"""Connect a Python application to the EEG_API_Unicorn engine over LSL. Do not edit this file:
the settings are in config.json, and your application is the function that receives the
decisions (see example.py).

    from eeg_api_lsl import EegApi, load_config

    api = EegApi(load_config("config.json"))
    api.connect()                      # waits until the console connects this application
    api.start()                        # sends the settings of config.json, starts the mode
    for decision in api.decisions():   # one dict per decision, channels by name
        ...                            # your application
    api.close()                        # stops the mode it started, closes the streams

The handshake follows docs/control.md: open the engine's reply streams, create the command stream
(its source_id is the name the console lists), wait until the engine reads it, then send the
commands, each with a unique "ref". With the console, someone has to click "Connect an
application", pick this application, then "Connect". With `server.py` alone, an application of
the same computer is heard at once.

Only dependency: pylsl (`pip install pylsl`).
"""

import json
import os
import time
import uuid

from pylsl import IRREGULAR_RATE, StreamInfo, StreamInlet, StreamOutlet, resolve_byprop

CONTROL_STREAM = "EEG_API_Unicorn_control"
REPLIES_STREAM = "EEG_API_Unicorn_replies"
STATUS_STREAM = "EEG_API_Unicorn_status"
DECODED_PREFIX = "EEG_API_Unicorn_decoded_"
REPLY_TIMEOUT_S = 5.0       # a reply that has not arrived after this long will not arrive

DEFAULTS = {
    "app_name": "my-app",
    "mode": "ssvep",
    "params": {},
    "propose_refresh_hz": 0,
    "stop_mode_on_exit": True,
    "search_timeout_s": 30,
}


def load_config(path):
    """The settings of config.json, completed with the defaults above."""
    with open(path, encoding="utf-8") as f:
        config = json.load(f)
    unknown = sorted(set(config) - set(DEFAULTS))
    if unknown:
        raise ValueError(f"{path}: unknown setting(s) {', '.join(unknown)}; "
                         f"known: {', '.join(DEFAULTS)}")
    return dict(DEFAULTS, **config)


class EegApiError(Exception):
    """A step that did not get the expected reply. The message says which, and why."""


class EegApi:
    """The link to one engine: the command stream we create, the reply streams we read."""

    def __init__(self, config, log=print):
        self.config = dict(DEFAULTS, **config)
        self.log = log
        # A random part makes the name unique: two copies of the application, on one computer
        # or on several, never take each other's replies.
        self.name = f"{self.config['app_name']}-{uuid.uuid4().hex[:6]}"
        self.mode = self.config["mode"]
        info = StreamInfo(CONTROL_STREAM, "Markers", 1, IRREGULAR_RATE, "string", self.name)
        self.outlet = StreamOutlet(info)
        self.replies = []           # (inlet, engine id): every reply stream of the network
        self.engine_id = None       # the engine that answered us first
        self.inbox = []
        self.disconnection = None   # the engine's "disconnected" message meant for us
        self.sent = 0
        self.started_here = False

    # --- the handshake ---------------------------------------------------------------------

    def connect(self):
        """Opens the reply streams of the network, then waits (with no time limit) until the
        engine reads our command stream. Raises EegApiError when no engine runs."""
        deadline = time.monotonic() + float(self.config["search_timeout_s"])
        while not self.replies and time.monotonic() < deadline:
            # `minimum` is never reached: the call waits the whole second and returns EVERY
            # reply stream that answered (there may be several engines on the network).
            for info in {i.uid(): i for i in resolve_byprop("name", REPLIES_STREAM,
                                                             minimum=1000, timeout=1.0)}.values():
                inlet = StreamInlet(info)
                try:
                    inlet.open_stream(timeout=2.0)    # listen BEFORE the first command
                except Exception:
                    continue                          # an engine that has just quit
                self.replies.append((inlet, info.source_id().partition("@")[2]))
        if not self.replies:
            raise EegApiError("no engine on the network: is the console (or server.py) running?")
        # A command pushed before the engine reads our stream is lost: wait for it.
        slices = 0
        while not self.outlet.wait_for_consumers(1.0):
            if slices % 10 == 0:
                self.log(f"Waiting to be connected: in the console, click \"Connect an "
                         f"application\", pick '{self.name}', then \"Connect\".")
            slices += 1
        self.log(f"Connected as '{self.name}'")

    def connected(self):
        """False as soon as the engine has said it stopped reading our command stream (do not
        rely on have_consumers() alone: it stays true until our next push)."""
        self._poll()
        return self.disconnection is None and self.outlet.have_consumers()

    def why_disconnected(self):
        if self.disconnection is None:
            return "no engine reads our commands any more"
        cause = self.disconnection.get("cause")
        if cause == "console":
            return "disconnected in the console"
        if cause == "engine_stopped":
            return "the engine stopped"
        return f"disconnected: {self.disconnection.get('reason')}"

    # --- commands ------------------------------------------------------------------------------

    def send(self, cmd, params=None):
        """Sends one command of docs/control.md for our mode and returns ITS reply (a dict).
        Sends it again once if the reply is lost (the four commands are safe to repeat)."""
        for _attempt in range(2):
            if not self.connected():
                raise EegApiError(self.why_disconnected())
            self.sent += 1
            command = {"cmd": cmd, "mode": self.mode, "ref": f"{self.name}-{self.sent}"}
            if params is not None:
                command["params"] = params
            self.log(f"-> {json.dumps(command)}")
            self.outlet.push_sample([json.dumps(command)])
            deadline = time.monotonic() + REPLY_TIMEOUT_S
            while time.monotonic() < deadline:
                self._poll()
                for reply in self.inbox:
                    if reply.get("ref") == command["ref"] and "event" not in reply:
                        self.log(f"<- {json.dumps(reply)}")
                        return reply
                if self.disconnection is not None:
                    raise EegApiError(self.why_disconnected())
                time.sleep(0.02)
        raise EegApiError(f"{cmd}: no reply")

    def start(self):
        """Sends the settings of config.json, then starts the mode. For an SSVEP shown on a
        screen, `propose_refresh_hz` first asks the engine for frequencies that divide that
        refresh rate. Returns the start_mode reply; raises EegApiError on a refusal."""
        params = dict(self.config["params"])
        refresh = float(self.config["propose_refresh_hz"] or 0)
        if refresh > 0:
            proposed = self.send("propose_params", {"refresh_hz": refresh})
            if not proposed.get("accepted"):
                raise EegApiError(f"propose_params: {proposed.get('reason')}")
            params.update({"refresh_hz": refresh, proposed["key"]: proposed["value"]})
        if params:
            reply = self.send("set_params", params)
            if not reply.get("accepted"):
                raise EegApiError(f"set_params: {reply.get('reason')}")
        reply = self.send("start_mode")
        if not reply.get("accepted"):
            raise EegApiError(f"start_mode: {reply.get('reason')}")
        # Stop only what WE started: a mode that was already running belongs to someone else.
        self.started_here = not reply.get("already_running")
        if reply.get("deferred"):
            self.log("This mode needs a model: in the console, choose it, then click "
                     "\"Start decoding\".")
        return reply

    # --- decisions -----------------------------------------------------------------------------

    def decisions(self):
        """Yields every decision of our mode as a dict {channel name: value}, -1 included
        (-1 means "no decision", never target 0). Waits for the mode to run (warm-up, rest,
        or the choice of a model in the console), opens the stream again when the engine
        recreates it, and ends when the link ends."""
        inlet, labels = None, []
        while self.connected():
            if inlet is None:
                inlet, labels = self._open_decoded()
                if inlet is None:
                    continue
            try:
                sample, _timestamp = inlet.pull_sample(timeout=0.2)
            except Exception:           # the engine recreated the stream: open it again
                inlet = None
                continue
            if sample is not None:
                yield dict(zip(labels, sample))
        self.log(self.why_disconnected())

    def _open_decoded(self):
        """The decoded stream of our mode, on OUR engine (every engine publishes under the
        same name; the source_id "name@engine id" tells them apart), with its channel names."""
        if self.engine_id is not None:
            found = resolve_byprop("source_id", f"{DECODED_PREFIX}{self.mode}@{self.engine_id}",
                                   timeout=0.5)
        else:       # no reply yet: the first engine that publishes this mode
            found = resolve_byprop("name", f"{DECODED_PREFIX}{self.mode}", timeout=0.5)
        for info in found:
            inlet = StreamInlet(info)
            try:
                inlet.open_stream(timeout=1.0)
                full = inlet.info(timeout=2.0)
            except Exception:
                continue
            channels, labels = full.desc().child("channels").child("channel"), []
            while not channels.empty():
                labels.append(channels.child_value("label"))
                channels = channels.next_sibling()
            return inlet, labels or [f"ch{i}" for i in range(full.channel_count())]
        return None, []

    # --- the end -------------------------------------------------------------------------------

    def close(self):
        """Stops the mode we started (if `stop_mode_on_exit`), then closes our streams: with
        the console, the connection ends with them."""
        try:
            if self.started_here and self.config["stop_mode_on_exit"] and self.connected():
                self.send("stop_mode")
        except EegApiError:
            pass
        self.replies.clear()
        del self.outlet

    def _poll(self):
        """Reads every waiting reply and keeps those meant for us."""
        for inlet, engine_id in self.replies:
            while True:
                try:
                    sample, _timestamp = inlet.pull_sample(timeout=0.0)
                except Exception:
                    break
                if sample is None:
                    break
                try:
                    reply = json.loads(sample[0])
                except ValueError:
                    continue
                if not isinstance(reply, dict):
                    continue
                if reply.get("event") == "disconnected":
                    if (reply.get("app") == self.name and self.disconnection is None
                            and self.engine_id in (None, engine_id)):
                        self.disconnection = reply
                    continue
                if not str(reply.get("ref")).startswith(f"{self.name}-"):
                    continue            # a reply to another application
                if self.engine_id is None:
                    self.engine_id = engine_id
                if engine_id == self.engine_id:
                    self.inbox.append(reply)


def config_path(name="config.json"):
    """config.json next to the script that runs, whatever the current folder."""
    import __main__
    here = os.path.dirname(os.path.abspath(getattr(__main__, "__file__", "."))) or "."
    return os.path.join(here, name)
